    <div id="styler-container"></div>
    <script>
        (function() {
            // SillyTavern will inject the user's message here.
            // Example message from Eden System: "[选择] 探索废墟\n\n系统自动记录:\n  - 购买物品: ... "
            const rawInput = `$1`;
            const container = document.getElementById('styler-container');

            // The trigger for a system log in Eden is the presence of the YAML block.
            const isSystemLog = rawInput.includes('系统自动记录:');

            if (isSystemLog) {
                // --- Render as a System Log ---
                const parts = rawInput.split('系统自动记录:');

                // The first part is always the choice text. Clean it up.
                const choiceText = parts[0].replace(/{{USER}}/g, '').replace(/\[选择\]/g, '').trim() || '执行系统操作';

                // Parse the YAML-like log content
                const logContent = '系统自动记录:' + parts.slice(1).join('系统自动记录:');
                const logEntries = parseSystemLog(logContent);

                // Generate timestamp
                const now = new Date();
                const timestamp = `[${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}]`;

                container.innerHTML = `
                    <div class="styler-wrapper system-log-card">
                        <div class="header">
                            <i class="fas fa-clipboard-list"></i> 
                            系统交互: 玩家选择了"${choiceText}"
                            <span class="timestamp">${timestamp}</span>
                        </div>
                        <div class="content">${renderLogEntries(logEntries)}</div>
                    </div>
                `;

            } else {
                // --- Render as a normal User Choice ---
                // Clean up the `[选择]` prefix for a cleaner display.
                const cleanedInput = rawInput.replace(/{{USER}}/g, '').replace(/\[选择\]/g, '').trim();
                const sanitizedInput = cleanedInput.replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\\n/g, "<br>");

                container.innerHTML = `
                    <div class="styler-wrapper user-choice-card">
                        <div class="header"><i class="fas fa-comment-dots"></i> 玩家选择</div>
                        <div class="content">${sanitizedInput}</div>
                    </div>
                `;
            }

            // Parse system log function
            function parseSystemLog(logText) {
                const entries = [];
                const lines = logText.split('\n');
                let currentEntry = null;

                for (let line of lines) {
                    line = line.trim();
                    if (line.startsWith('- ')) {
                        // New entry
                        if (currentEntry) {
                            entries.push(currentEntry);
                        }
                        const actionType = line.substring(2).replace(':', '').trim();
                        currentEntry = {
                            type: actionType,
                            data: {}
                        };
                    } else if (line.includes(':') && currentEntry) {
                        // Property of current entry
                        const [key, value] = line.split(':').map(s => s.trim());
                        if (key && value) {
                            currentEntry.data[key] = value;
                        }
                    }
                }
                if (currentEntry) {
                    entries.push(currentEntry);
                }
                return entries;
            }

            // Render log entries function
            function renderLogEntries(entries) {
                if (entries.length === 0) {
                    return '<div class="log-entry"><div class="log-entry-content">暂无系统操作记录</div></div>';
                }

                return entries.map(entry => {
                    const { type, data } = entry;

                    // Determine icon and style based on action type
                    let iconClass = 'fas fa-cog';
                    let iconStyle = 'purchase';
                    let title = type;
                    let details = '';
                    let price = '';

                    if (type === '购买物品') {
                        iconClass = 'fas fa-shopping-cart';
                        iconStyle = 'purchase';
                        title = `购买: ${data.itemName || data.itemId || '未知物品'}`;
                        if (data.itemId) {
                            details += `物品ID: <span class="item-id">${data.itemId}</span><br>`;
                        }
                        if (data.price) {
                            price = `¥${parseInt(data.price).toLocaleString()}`;
                            details += `消费金额: <span class="highlight-price">¥${parseInt(data.price).toLocaleString()}</span>`;
                        }
                    } else if (type === '使用物品') {
                        iconClass = 'fas fa-hand-paper';
                        iconStyle = 'use';
                        title = `使用: ${data.itemName || data.itemId || '未知物品'}`;
                        if (data.itemId) {
                            details += `物品ID: <span class="item-id">${data.itemId}</span><br>`;
                        }
                        if (data.quantity) {
                            details += `使用数量: ${data.quantity}`;
                        }
                    } else if (type === '丢弃物品') {
                        iconClass = 'fas fa-trash';
                        iconStyle = 'discard';
                        title = `丢弃: ${data.itemName || data.itemId || '未知物品'}`;
                        if (data.itemId) {
                            details += `物品ID: <span class="item-id">${data.itemId}</span><br>`;
                        }
                        if (data.quantity) {
                            details += `丢弃数量: ${data.quantity}`;
                        }
                    }

                    return `
                        <div class="log-entry">
                            <div class="log-entry-icon ${iconStyle}">
                                <i class="${iconClass}"></i>
                            </div>
                            <div class="log-entry-content">
                                <div class="log-entry-title">${title}</div>
                                <div class="log-entry-details">${details}</div>
                            </div>
                            ${price ? `<div class="log-entry-price">${price}</div>` : ''}
                        </div>
                    `;
                }).join('');
            }
        })();
    </script>
</body>
