/**
 * AI回复JSON提取器
 * 功能：从最新AI回复中提取JSON/YAML内容，根据声明对聊天变量表进行增删查改操作
 * 支持：JSON优先，YAML备选，混合模式（多个操作顺序执行）
 * 作者：基于变量表.JS优化
 */

// 动态加载js-yaml库
if (typeof window.jsyaml === 'undefined') {
    const script = document.createElement('script');
    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/js-yaml/4.1.0/js-yaml.min.js';
    script.onload = () => {
        console.log('[YAML支持] js-yaml库加载成功');
        window.jsyaml = jsyaml;
    };
    script.onerror = () => {
        console.warn('[YAML支持] js-yaml库加载失败，YAML功能将不可用');
    };
    document.head.appendChild(script);
}

class AIReplyJSONExtractor {
    constructor() {
        this.variableTableKey = 'json_data_table'; // JSON数据表键名
        this.operationLogKey = 'json_operations_log'; // 操作日志键名
        this.enableLogging = false; // 是否启用日志记录
    }

    /**
     * 根据消息ID获取AI的回复内容，并验证是否为AI回复
     * @param {number} messageId - 消息ID
     * @returns {Promise<string|null>} AI回复内容，如果不是AI回复则返回null
     */
    async getVerifiedAIReplyById(messageId) {
        try {
            const messages = await getChatMessages(`${messageId}-${messageId}`);
            if (!messages || messages.length === 0) {
                console.log(`[AI回复提取] 未找到ID为 ${messageId} 的消息`);
                return null;
            }

            const message = messages[0];

            // 主要判断依据：role属性
            const isAIReply = message.role === 'assistant';
            // 兼容性判断：检查is_user属性
            const isNotUser = message.is_user === false;

            if (isAIReply || isNotUser) {
                console.log(`[AI回复提取] 确认ID ${messageId} 为AI回复 (role: ${message.role}, is_user: ${message.is_user})。`);
                const reply = message.message;
                console.log(`[AI回复提取] 获取到AI回复，长度: ${reply.length} 字符`);
                return reply;
            } else {
                console.log(`[AI回复提取] ID ${messageId} 不是AI回复 (role: ${message.role}, is_user: ${message.is_user})，跳过处理。`);
                return null;
            }
        } catch (error) {
            console.error(`[AI回复提取] 获取或验证ID为 ${messageId} 的AI回复失败:`, error);
            return null;
        }
    }

    /**
     * 从文本中提取YAML内容
     * @param {string} text - 要提取的文本
     * @returns {Object|null} 提取到的YAML对象
     */
    extractYAMLFromText(text) {
        if (!text || typeof window.jsyaml === 'undefined') {
            if (typeof window.jsyaml === 'undefined') {
                console.log('[YAML提取] js-yaml库未加载，跳过YAML提取');
            }
            return null;
        }

        try {
            console.log('[YAML提取] 开始提取YAML内容...');

            // YAML提取模式
            const yamlPatterns = [
                // 匹配```yaml...```格式
                /```yaml\s*([\s\S]*?)\s*```/gi,
                // 匹配```yml...```格式
                /```yml\s*([\s\S]*?)\s*```/gi,
                // 匹配以---开头的YAML格式
                /^---\s*\n([\s\S]*?)(?:\n---|\n\.\.\.|$)/gm
            ];

            for (let i = 0; i < yamlPatterns.length; i++) {
                const pattern = yamlPatterns[i];
                const matches = text.match(pattern);

                if (matches) {
                    console.log(`[YAML提取] 使用模式${i+1}找到${matches.length}个匹配项`);

                    for (const match of matches) {
                        try {
                            // 清理代码块标记
                            let cleanYaml = match
                                .replace(/```yaml\s*/g, '')
                                .replace(/```yml\s*/g, '')
                                .replace(/```\s*/g, '')
                                .replace(/^---\s*\n/g, '')
                                .replace(/\n---$/g, '')
                                .replace(/\n\.\.\.$/g, '')
                                .trim();

                            const parsed = window.jsyaml.load(cleanYaml);

                            if (parsed && typeof parsed === 'object') {
                                console.log('[YAML提取] 成功提取YAML对象:', Object.keys(parsed));
                                return parsed;
                            }
                        } catch (e) {
                            console.log('[YAML提取] 解析YAML失败:', e.message);
                            continue; // 尝试下一个匹配项
                        }
                    }
                }
            }

            // 尝试直接解析整个文本为YAML
            console.log('[YAML提取] 尝试直接解析整个文本为YAML...');
            const parsed = window.jsyaml.load(text);
            if (parsed && typeof parsed === 'object') {
                console.log('[YAML提取] 成功解析整个文本为YAML');
                return parsed;
            }

        } catch (error) {
            console.log('[YAML提取] 未能提取到有效YAML:', error.message);
        }

        return null;
    }

    /**
     * 从文本中提取多个JSON/YAML块（混合模式）
     * @param {string} text - 要提取的文本
     * @returns {Array} 提取到的数据块数组
     */
    extractMultipleDataBlocks(text) {
        if (!text) return [];

        console.log('[混合模式] 开始提取多个数据块...');
        const dataBlocks = [];

        // 定义所有可能的数据块模式（优先级从高到低）
        const patterns = [
            // YAML相关模式（优先级更高，避免被通用模式覆盖）
            { type: 'yaml', pattern: /```yaml\s*([\s\S]*?)\s*```/gi, priority: 1 },
            { type: 'yaml', pattern: /```yml\s*([\s\S]*?)\s*```/gi, priority: 1 },
            { type: 'yaml', pattern: /^---\s*\n([\s\S]*?)(?:\n---|\n\.\.\.|$)/gm, priority: 1 },
            // JSON相关模式
            { type: 'json', pattern: /```json\s*([\s\S]*?)\s*```/gi, priority: 2 },
            { type: 'json', pattern: /\{[\s\S]*?\}/g, priority: 3 },
            // 通用代码块模式（最低优先级，只匹配不被其他模式覆盖的）
            { type: 'json', pattern: /```\s*([\s\S]*?)\s*```/gi, priority: 4 }
        ];

        // 收集所有匹配项及其位置
        const allMatches = [];

        for (const patternInfo of patterns) {
            let match;
            const regex = new RegExp(patternInfo.pattern.source, patternInfo.pattern.flags);

            while ((match = regex.exec(text)) !== null) {
                allMatches.push({
                    type: patternInfo.type,
                    content: match[1] || match[0],
                    start: match.index,
                    end: match.index + match[0].length,
                    raw: match[0],
                    priority: patternInfo.priority
                });
            }
        }

        // 按位置排序
        allMatches.sort((a, b) => a.start - b.start);

        // 智能去重：保留优先级更高的匹配项
        const uniqueMatches = [];
        for (const match of allMatches) {
            const overlapping = uniqueMatches.filter(existing => 
                (match.start >= existing.start && match.start < existing.end) ||
                (match.end > existing.start && match.end <= existing.end) ||
                (existing.start >= match.start && existing.start < match.end) ||
                (existing.end > match.start && existing.end <= match.end)
            );

            if (overlapping.length === 0) {
                // 没有重叠，直接添加
                uniqueMatches.push(match);
            } else {
                // 有重叠，检查优先级
                const lowestPriority = Math.min(...overlapping.map(m => m.priority));
                if (match.priority <= lowestPriority) {
                    // 当前匹配项优先级更高或相等，移除重叠的低优先级项
                    for (let i = uniqueMatches.length - 1; i >= 0; i--) {
                        const existing = uniqueMatches[i];
                        const isOverlapping = 
                            (match.start >= existing.start && match.start < existing.end) ||
                            (match.end > existing.start && match.end <= existing.end) ||
                            (existing.start >= match.start && existing.start < match.end) ||
                            (existing.end > match.start && existing.end <= match.end);

                        if (isOverlapping && existing.priority >= match.priority) {
                            uniqueMatches.splice(i, 1);
                        }
                    }
                    uniqueMatches.push(match);
                }
            }
        }

        // 重新按位置排序
        uniqueMatches.sort((a, b) => a.start - b.start);

        console.log(`[混合模式] 找到${uniqueMatches.length}个候选数据块`);

        // 解析每个数据块
        for (let i = 0; i < uniqueMatches.length; i++) {
            const match = uniqueMatches[i];
            try {
                let parsed = null;
                let cleanContent = match.content;

                if (match.type === 'json') {
                    // 清理JSON内容
                    cleanContent = cleanContent
                        .replace(/```json\s*/g, '')
                        .replace(/```\s*/g, '')
                        .trim();

                    parsed = JSON.parse(cleanContent);
                } else if (match.type === 'yaml' && typeof window.jsyaml !== 'undefined') {
                    // 清理YAML内容
                    cleanContent = cleanContent
                        .replace(/```yaml\s*/g, '')
                        .replace(/```yml\s*/g, '')
                        .replace(/```\s*/g, '')
                        .replace(/^---\s*\n/g, '')
                        .replace(/\n---$/g, '')
                        .replace(/\n\.\.\.$/g, '')
                        .trim();

                    parsed = window.jsyaml.load(cleanContent);
                }

                if (parsed && typeof parsed === 'object') {
                    dataBlocks.push({
                        index: i,
                        type: match.type,
                        data: parsed,
                        position: match.start
                    });
                    console.log(`[混合模式] 成功解析第${i+1}个${match.type.toUpperCase()}块:`, Object.keys(parsed));
                }
            } catch (error) {
                console.log(`[混合模式] 解析第${i+1}个${match.type.toUpperCase()}块失败:`, error.message);
            }
        }

        console.log(`[混合模式] 总共提取到${dataBlocks.length}个有效数据块`);
        return dataBlocks;
    }

    /**
     * 从文本中提取JSON/YAML内容（优先JSON，支持混合模式）
     * @param {string} text - 要提取的文本
     * @returns {Object|Array|null} 提取到的数据对象或数据块数组
     */
    extractDataFromText(text) {
        if (!text) return null;

        try {
            console.log('[数据提取] 开始提取JSON/YAML内容...');

            // 首先尝试提取多个数据块（混合模式）
            const multipleBlocks = this.extractMultipleDataBlocks(text);
            if (multipleBlocks.length > 1) {
                console.log(`[数据提取] 检测到混合模式，包含${multipleBlocks.length}个数据块`);
                return multipleBlocks;
            } else if (multipleBlocks.length === 1) {
                console.log('[数据提取] 单个数据块模式');
                return multipleBlocks[0].data;
            }

            // 如果没有找到多个块，尝试单个JSON提取
            console.log('[数据提取] 尝试单个JSON提取...');
            const jsonResult = this.extractJSONFromText(text);
            if (jsonResult) {
                console.log('[数据提取] JSON提取成功');
                return jsonResult;
            }

            // 如果JSON失败，尝试YAML提取
            console.log('[数据提取] JSON提取失败，尝试YAML提取...');
            const yamlResult = this.extractYAMLFromText(text);
            if (yamlResult) {
                console.log('[数据提取] YAML提取成功');
                return yamlResult;
            }

            console.log('[数据提取] 未能提取到任何有效数据');
            return null;

        } catch (error) {
            console.error('[数据提取] 提取过程中发生错误:', error);
            return null;
        }
    }

    /**
     * 从文本中提取JSON内容（保持向后兼容）
     * @param {string} text - 要提取的文本
     * @returns {Object|null} 提取到的JSON对象
     */
    extractJSONFromText(text) {
        if (!text) return null;

        try {
            console.log('[JSON提取] 开始提取JSON内容...');

            // 尝试多种JSON提取方法
            const jsonPatterns = [
                // 匹配```json...```格式
                /```json\s*([\s\S]*?)\s*```/gi,
                // 匹配```...```格式（可能是JSON）
                /```\s*([\s\S]*?)\s*```/gi,
                // 匹配{...}格式（完整JSON对象）
                /\{[\s\S]*?\}/g
            ];

            for (let i = 0; i < jsonPatterns.length; i++) {
                const pattern = jsonPatterns[i];
                const matches = text.match(pattern);

                if (matches) {
                    console.log(`[JSON提取] 使用模式${i+1}找到${matches.length}个匹配项`);

                    for (const match of matches) {
                        try {
                            // 清理代码块标记
                            let cleanJson = match
                                .replace(/```json\s*/g, '')
                                .replace(/```\s*/g, '')
                                .trim();

                            const parsed = JSON.parse(cleanJson);

                            if (parsed && typeof parsed === 'object') {
                                console.log('[JSON提取] 成功提取JSON对象:', Object.keys(parsed));
                                return parsed;
                            }
                        } catch (e) {
                            continue; // 尝试下一个匹配项
                        }
                    }
                }
            }

            // 如果以上方法都失败，尝试直接解析整个文本
            console.log('[JSON提取] 尝试直接解析整个文本...');
            return JSON.parse(text);

        } catch (error) {
            console.log('[JSON提取] 未能提取到有效JSON:', error.message);
            return null;
        }
    }

    /**
     * 获取当前的JSON变量表
     * @returns {Object} JSON变量表
     */
    getJSONTable() {
        try {
            const variables = getVariables({ type: 'chat' });
