    /**
     * 记录操作日志
     * @param {string} operation - 操作类型
     * @param {Object} data - 操作数据
     */
    async logOperation(operation, data) {
        if (!this.enableLogging) return;

        try {
            const variables = getVariables({ type: 'chat' });
            const logs = variables[this.operationLogKey] || [];

            logs.push({
                timestamp: new Date().toISOString(),
                operation: operation,
                data: JSON.stringify(data, null, 2)
            });

            // 只保留最近30条日志（避免占用过多空间）
            if (logs.length > 30) {
                logs.splice(0, logs.length - 30);
            }

            await insertOrAssignVariables({
                [this.operationLogKey]: logs
            }, { type: 'chat' });
        } catch (error) {
            console.error('[日志记录] 记录操作日志失败:', error);
        }
    }

    /**
     * 检测JSON中的操作类型和数据结构
     * @param {Object} jsonData - JSON数据
     * @returns {Object} 操作分析结果
     */
    analyzeJSONOperations(jsonData) {
        const analysis = {
            operationType: 'replace', // 默认为替换操作
            hasOperationFlags: false,
            data: jsonData
        };

        // 检查是否有操作标识
        if (jsonData.hasOwnProperty('$operation')) {
            analysis.hasOperationFlags = true;
            analysis.operationType = jsonData.$operation;
            analysis.data = { ...jsonData };
            delete analysis.data.$operation;
        } else if (jsonData.hasOwnProperty('$update')) {
            analysis.hasOperationFlags = true;
            analysis.operationType = 'update';
            analysis.data = jsonData.$update;
        } else if (jsonData.hasOwnProperty('$delete')) {
            analysis.hasOperationFlags = true;
            analysis.operationType = 'delete';
            analysis.deletePaths = Array.isArray(jsonData.$delete) ? jsonData.$delete : [jsonData.$delete];
        } else if (jsonData.hasOwnProperty('$clear')) {
            analysis.hasOperationFlags = true;
            analysis.operationType = 'clear';
        }

        console.log(`[操作分析] 检测到操作类型: ${analysis.operationType}`);
        return analysis;
    }

    /**
     * 深度拷贝对象
     * @param {Object} obj - 要拷贝的对象
     * @returns {Object} 拷贝后的对象
     */
    deepCopy(obj) {
        if (obj === null || typeof obj !== 'object') {
            return obj;
        }

        if (Array.isArray(obj)) {
            return obj.map(item => this.deepCopy(item));
        }

        const copy = {};
        for (const key in obj) {
            if (obj.hasOwnProperty(key)) {
                copy[key] = this.deepCopy(obj[key]);
            }
        }

        return copy;
    }

    /**
     * 根据路径设置对象的属性值，如果路径不存在则会创建
     * @param {Object} obj - 目标对象
     * @param {string} path - 属性路径，如 "用户信息.姓名"
     * @param {any} value - 要设置的值
     */
    setByPath(obj, path, value) {
        const keys = path.split('.');
        let current = obj;

        for (let i = 0; i < keys.length - 1; i++) {
            const key = keys[i];
            // 如果路径中的节点不是对象或不存在，则创建它
            if (typeof current[key] !== 'object' || current[key] === null) {
                current[key] = {};
            }
            current = current[key];
        }

        const lastKey = keys[keys.length - 1];
        current[lastKey] = value;
        console.log(`[路径更新] 成功设置路径 "${path}"`);
    }

    /**
     * 深度合并对象
     * @param {Object} target - 目标对象
     * @param {Object} source - 源对象
     * @returns {Object} 合并后的对象
     */
    deepMerge(target, source) {
        const result = { ...target };

        for (const key in source) {
            if (source.hasOwnProperty(key)) {
                if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
                    result[key] = this.deepMerge(result[key] || {}, source[key]);
                } else {
                    result[key] = source[key];
                }
            }
        }

        return result;
    }

    /**
     * 根据路径删除对象属性
     * @param {Object} obj - 目标对象
     * @param {string} path - 属性路径，如 "用户信息.姓名"
     */
    deleteByPath(obj, path) {
        const keys = path.split('.');
        let current = obj;

        // 遍历到倒数第二级对象
        for (let i = 0; i < keys.length - 1; i++) {
            if (current[keys[i]] && typeof current[keys[i]] === 'object') {
                current = current[keys[i]];
            } else {
                console.log(`[删除] 路径 "${path}" 中的 "${keys[i]}" 不存在或不是对象`);
                return false;
            }
        }

        const lastKey = keys[keys.length - 1];
        if (current.hasOwnProperty(lastKey)) {
            delete current[lastKey];
            console.log(`[删除] 成功删除路径 "${path}"`);
            return true;
        } else {
            console.log(`[删除] 路径 "${path}" 的最终键 "${lastKey}" 不存在`);
            return false;
        }
    }

    /**
     * 执行JSON操作并更新变量表
     * @param {Object} analysis - 操作分析结果
     * @returns {boolean} 操作是否成功
     */
    async executeJSONOperations(analysis) {
        try {
            const currentTable = this.getJSONTable();
            let newTable;
            let operationDesc = '';

            switch (analysis.operationType) {
                case 'replace':
                    // 无声明标识 = 清空旧数据然后写入新数据（完整替换）
                    newTable = analysis.data;
                    operationDesc = '完整替换';
                    console.log(`[变量更新] 执行完整替换操作，新数据键: ${Object.keys(newTable)}`);
                    break;

                case 'update':
                    // 增量更新，支持路径更新
                    newTable = this.deepCopy(currentTable); // 使用深拷贝以避免修改原始对象
                    operationDesc = '增量更新';
                    console.log(`[变量更新] 执行增量更新操作，更新内容:`, analysis.data);

                    for (const key in analysis.data) {
                        if (analysis.data.hasOwnProperty(key)) {
                            const value = analysis.data[key];
                            if (key.includes('.')) {
                                // 识别为路径更新
                                this.setByPath(newTable, key, value);
                            } else {
                                // 识别为顶层或嵌套对象合并
                                if (typeof newTable[key] === 'object' && newTable[key] !== null && typeof value === 'object' && value !== null && !Array.isArray(value)) {
                                    newTable[key] = this.deepMerge(newTable[key], value);
                                } else {
                                    newTable[key] = value;
                                }
                            }
                        }
                    }
                    break;

                case 'delete':
                    // 使用专门的删除变量函数
                    let deletedCount = 0;
                    for (const path of analysis.deletePaths || []) {
                        try {
                            // 构建完整的变量路径：json_data_table.用户信息.年龄
                            const fullPath = `${this.variableTableKey}.${path}`;
                            const success = await deleteVariable(fullPath, { type: 'chat' });
                            if (success) {
                                deletedCount++;
                                console.log(`[变量更新] 删除路径: ${path} - 成功`);
                            } else {
                                console.log(`[变量更新] 删除路径: ${path} - 失败（路径不存在）`);
                            }
                        } catch (error) {
                            console.error(`[变量更新] 删除路径 ${path} 失败:`, error);
                        }
                    }
                    operationDesc = `删除 ${deletedCount}/${analysis.deletePaths?.length || 0} 项`;

                    // 删除操作不需要再次更新变量表，因为deleteVariable已经直接操作了
                    await this.logOperation(`AI回复-${operationDesc}`, {
                        operationType: analysis.operationType,
                        dataKeys: [],
                        deletePaths: analysis.deletePaths || null
                    });

                    console.log(`[变量更新] ${operationDesc}操作成功完成`);
                    return true;

                case 'clear':
                    // 清空所有数据
                    newTable = {};
                    operationDesc = '清空所有数据';
                    console.log('[变量更新] 执行清空操作');
                    break;

                default:
                    console.warn(`[变量更新] 未知操作类型: ${analysis.operationType}`);
                    return false;
            }

            // 更新变量表
            await insertOrAssignVariables({
                [this.variableTableKey]: newTable
            }, { type: 'chat' });

            // 记录操作日志
            await this.logOperation(`AI回复-${operationDesc}`, {
                operationType: analysis.operationType,
                dataKeys: analysis.data ? Object.keys(analysis.data) : [],
                deletePaths: analysis.deletePaths || null
            });

            console.log(`[变量更新] ${operationDesc}操作成功完成`);
            return true;

        } catch (error) {
            console.error('[变量更新] 执行操作失败:', error);
            return false;
        }
    }

    /**
     * 处理混合模式数据（多个操作顺序执行）
     * @param {Array} dataBlocks - 数据块数组
     * @returns {boolean} 处理是否成功
     */
    async processMixedModeData(dataBlocks) {
        console.log(`\n=== 开始处理混合模式数据（${dataBlocks.length}个操作）===`);

        let successCount = 0;
        let totalOperations = dataBlocks.length;

        for (let i = 0; i < dataBlocks.length; i++) {
            const block = dataBlocks[i];

            try {
                console.log(`\n--- 处理第${i+1}/${totalOperations}个操作 (${block.type.toUpperCase()}) ---`);

                // 分析操作类型
                const analysis = this.analyzeJSONOperations(block.data);

                // 执行操作
                const success = await this.executeJSONOperations(analysis);

                if (success) {
                    successCount++;
                    console.log(`[混合模式] 第${i+1}个操作执行成功`);
                } else {
                    console.log(`[混合模式] 第${i+1}个操作执行失败`);
                }

                // 添加短暂延迟以确保操作之间的顺序性
                await new Promise(resolve => setTimeout(resolve, 100));

            } catch (error) {
                console.error(`[混合模式] 第${i+1}个操作处理异常:`, error);
            }
        }

        console.log(`\n[混合模式] 处理完成：${successCount}/${totalOperations} 个操作成功`);

        // 记录混合模式操作日志
        await this.logOperation(`AI回复-混合模式(${successCount}/${totalOperations})`, {
            operationType: 'mixed',
            totalOperations: totalOperations,
            successCount: successCount,
            operations: dataBlocks.map((block, index) => ({
                index: index + 1,
                type: block.type,
                operationType: this.analyzeJSONOperations(block.data).operationType
            }))
        });

        return successCount > 0;
    }

    /**
     * 主要处理函数：从AI回复中提取JSON/YAML并更新变量表（支持混合模式）
     * @param {number} messageId - 触发事件的消息ID
     * @returns {boolean} 处理是否成功
     */
    async processAIReplyToJSON(messageId) {
        try {
