            const isSystemLog = rawInput.includes('系统自动记录:');

            if (isSystemLog) {
                // --- Render as a System Log ---
                const parts = rawInput.split('系统自动记录:');

                // The first part is always the choice text. Clean it up.
                const choiceText = parts[0].replace(/{{USER}}/g, '').replace(/\[选择\]/g, '').trim() || '执行系统操作';

                // Parse the YAML-like log content
                const logContent = '系统自动记录:' + parts.slice(1).join('系统自动记录:');
                const logEntries = parseSystemLog(logContent);

                // Generate timestamp
                const now = new Date();
                const timestamp = `[${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}]`;

                container.innerHTML = `
