                            <span class="timestamp">${timestamp}</span>
                        </div>
                        <div class="content">${renderLogEntries(logEntries)}</div>
                    </div>
                `;

            } else {
                // --- Render as a normal User Choice ---
                // Clean up the `[选择]` prefix for a cleaner display.
                const cleanedInput = rawInput.replace(/{{USER}}/g, '').replace(/\[选择\]/g, '').trim();
                const sanitizedInput = cleanedInput.replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\\n/g, "<br>");

                container.innerHTML = `
                    <div class="styler-wrapper user-choice-card">
                        <div class="header"><i class="fas fa-comment-dots"></i> 玩家选择</div>
                        <div class="content">${sanitizedInput}</div>
                    </div>
                `;
            }

            // Parse system log function
            function parseSystemLog(logText) {
                const entries = [];
                const lines = logText.split('\n');
                let currentEntry = null;

                for (let line of lines) {
                    line = line.trim();
                    if (line.startsWith('- ')) {
                        // New entry
                        if (currentEntry) {
                            entries.push(currentEntry);
                        }
                        const actionType = line.substring(2).replace(':', '').trim();
                        currentEntry = {
