                        iconClass = 'fas fa-shopping-cart';
                        iconStyle = 'purchase';
                        title = `购买: ${data.itemName || data.itemId || '未知物品'}`;
                        if (data.itemId) {
                            details += `物品ID: <span class="item-id">${data.itemId}</span><br>`;
