                        if (data.itemId) {
                            details += `物品ID: <span class="item-id">${data.itemId}</span><br>`;
                        }
                        if (data.quantity) {
                            details += `使用数量: ${data.quantity}`;
                        }
                    } else if (type === '丢弃物品') {
                        iconClass = 'fas fa-trash';
                        iconStyle = 'discard';
                        title = `丢弃: ${data.itemName || data.itemId || '未知物品'}`;
                        if (data.itemId) {
