        .achievement-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 15px; }
        .achievement-card { background: white; border: 2px solid #ddd; border-radius: 8px; padding: 15px; text-align: center; transition: all 0.3s ease; position: relative; }
        .achievement-card.unlocked { border-color: var(--accent-pink); background: linear-gradient(to bottom, #fff, rgba(255, 182, 193, 0.1)); }
        .achievement-card.locked { opacity: 0.6; filter: grayscale(1); }
        .achievement-icon { font-size: 48px; margin-bottom: 10px; color: var(--primary-blue); }
