        .erotic-status { border: 2px solid var(--accent-pink); background: rgba(255, 182, 193, 0.05); }
        .erotic-status h4 { color: var(--accent-pink); }
        @media (max-width: 768px) {
            #eden-container { margin: 10px; border-radius: 8px; }
            .nav-bar { padding: 10px 15px; }
            .nav-button span { display: none; }
