            .status-grid, .shop-items, .detail-grid, .achievement-grid { grid-template-columns: 1fr; }
            .storage-grid { grid-template-columns: repeat(auto-fill, minmax(80px, 1fr)); }
            .detail-grid { gap: 5px; }
            .status-tabs { gap: 5px; }
            .status-tab { padding: 6px 12px; font-size: 14px; }
        }
    </style>
</head>
<body>
    <!-- 模态框容器 -->
    <div id="modal-overlay" class="modal-overlay">
        <div class="modal">
            <h2 class="modal-title" id="modal-title"></h2>
            <div class="modal-content" id="modal-content"></div>
            <div class="modal-buttons" id="modal-buttons"></div>
        </div>
    </div>

    <!-- 主容器 -->
    <div id="eden-container">
        <!-- 导航栏 -->
        <nav class="nav-bar">
            <div class="nav-group">
                <button class="nav-button active" data-page="home"><i class="fas fa-home"></i><span>主页</span></button>
                <button class="nav-button" data-page="status"><i class="fas fa-chart-line"></i><span>状态</span></button>
                <button class="nav-button" data-page="shop"><i class="fas fa-shopping-cart"></i><span>购物</span></button>
                <button class="nav-button" data-page="storage"><i class="fas fa-box"></i><span>存储</span></button>
            </div>
            <div class="nav-group">
                <button class="send-to-st-btn" onclick="exportDataToST()" title="发送数据到SillyTavern">
                    <i class="fas fa-paper-plane"></i><span>发送到ST</span>
                </button>
                <div class="phase-indicator" id="phase-indicator">渗透期</div>
            </div>
        </nav>

        <!-- 主内容区域 -->
        <div id="main-content">
            <!-- 主页 -->
            <div id="page-home" class="page active">
                <div class="home-header">
                    <h1 id="home-title"></h1>
                    <p id="home-subtitle"></p>
                </div>
                <div class="scene-content" id="scene-content"></div>
            </div>

            <!-- 状态页 -->
            <div id="page-status" class="page">
                <h2>系统状态监控</h2>
                <div class="status-tabs" id="status-tabs-container"></div>
                <div id="status-content-container"></div>
            </div>

            <!-- 商店页 -->
            <div id="page-shop" class="page">
                <div class="shop-header">
                    <h2>UNDO商店</h2>
                    <div class="currency-display">
                        <i class="fas fa-yen-sign"></i>
                        <span id="shop-currency">0</span>
                    </div>
                </div>
                <div class="shop-items" id="shop-items"></div>
            </div>

            <!-- 存储页 -->
            <div id="page-storage" class="page">
                <h2>物品存储</h2>
                <div class="storage-grid" id="storage-grid"></div>
            </div>

        </div>

        <!-- 玩家选择面板 -->
        <div id="choices-panel" style="display: none;">
            <div class="choices-header" onclick="toggleChoices()">
                <span>玩家选择</span>
                <i class="fas fa-chevron-down choices-toggle" id="choices-toggle"></i>
            </div>
            <div class="choices-content" id="choices-content">
                <div class="choice-list" id="choice-list"></div>
            </div>
        </div>
    </div>

<script>
// ===================================================================================
// 伊甸园系统 - 增强版
// 修复了数据结构不一致，增强了记忆管理系统，扩展了状态信息
// ===================================================================================

class DataManager {
    static async loadGameData() {
        console.log("🚀 开始智能数据加载...");
        try {
            if (typeof getVariables === 'function') {
                const vars = getVariables({ type: 'chat' });
                if (vars.json_data_table && vars.json_data_table.gameData) {
                    console.log("✅ 从 JS-Slash-Runner 变量表加载数据");
                    return this.supplementStoryData(vars.json_data_table.gameData);
                }
            }
        } catch (e) {
            console.warn("⚠️ JS-Slash-Runner 加载失败:", e.message);
        }

        try {
            const xmlSource = document.getElementById('xml-data-source').value;
            if (xmlSource && xmlSource.trim() !== '') {
                const parsedData = this.parseInjectedContent(xmlSource);
                if (parsedData && parsedData.story && parsedData.choices) {
                     console.log("✅ 从 SillyTavern 注入数据加载");
                     return parsedData;
                }
            }
        } catch(e) {
             console.warn("⚠️ SillyTavern 注入数据解析失败:", e.message);
        }

        try {
            console.log("🔄 从外部 data.json 文件加载数据 (备用)");
            const response = await fetch('data.json');
            if (!response.ok) throw new Error(`HTTP 错误! 状态: ${response.status}`);
            const data = await response.json();
            return this.supplementStoryData(data.gameData);
        } catch (e) {
            console.error("❌ 所有数据源加载失败:", e);
            throw e;
        }
    }

    static supplementStoryData(data) {
        const xmlSource = document.getElementById('xml-data-source').value;
        if (xmlSource && xmlSource.trim() !== '') {
            const injected = this.parseInjectedContent(xmlSource);
            if (injected) {
                if (injected.story) data.story = { ...data.story, ...injected.story };
                if (injected.choices) data.choices = injected.choices;
                 console.log("📦 已从 SillyTavern 注入内容补充故事和选项");
            }
        }
        return data;
    }

    static parseInjectedContent(content) {
        try {
            if (typeof jsyaml !== 'undefined') {
                 const parsed = jsyaml.load(content);
                 if(typeof parsed === 'object') return parsed;
            }
        } catch (e) {
            try {
                 return JSON.parse(content);
            } catch(jsonError) {
                console.warn("⚠️ 注入内容既不是有效的YAML也不是JSON:", content);
            }
        }
        return null;
    }
}

// --- 全局状态 ---
let gameData = {};
let userActionLog = [];
let cachedExportData = null;

// --- 初始化 ---
document.addEventListener('DOMContentLoaded', initialize);

async function initialize() {
    console.log("正在初始化伊甸园系统...");
    try {
        gameData = await DataManager.loadGameData();
        setupEventListeners();
        showPage('home');
        console.log("伊甸园系统初始化成功。");
    } catch (error) {
        console.error("初始化失败:", error);
        document.body.innerHTML = `<div style="color: white; text-align: center; padding: 50px;">系统加载失败。请检查数据源或控制台输出。</div>`;
    }
}

function setupEventListeners() {
    document.querySelectorAll('.nav-button').forEach(button => {
        button.addEventListener('click', () => showPage(button.dataset.page));
    });
    document.querySelector('.modal-overlay').addEventListener('click', (e) => {
        if (e.target === e.currentTarget) hideModal();
    });
}

// --- 页面导航和渲染 ---
function showPage(pageId) {
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    document.getElementById(`page-${pageId}`).classList.add('active');
    document.querySelectorAll('.nav-button').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.page === pageId);
    });

    const renderFunctions = {
        home: renderHomePage,
        status: renderStatusPage,
        shop: renderShop,
        storage: renderStorage,
    };

    if(renderFunctions[pageId]) {
        renderFunctions[pageId]();
    }
    updateGeneralStatus();
}

function updateGeneralStatus() {
    document.title = gameData.config?.title || "伊甸园";
    // 从新的数据结构中获取当前阶段
    const phase = getDataByPath(gameData, 'system.eden.main.content')?.find(d => d.key === 'phase')?.value ||
                  getDataByPath(gameData, 'system.eden.details')?.find(d => d.key === 'phase')?.value ||
                  '未知阶段';
    document.getElementById('phase-indicator').textContent = phase;
}

// --- 数据访问辅助函数 ---
function getDataByPath(obj, path) {
    return path.split('.').reduce((current, key) => current && current[key], obj);
}

function safeGetValue(obj, path, defaultValue = null) {
    const result = getDataByPath(obj, path);
    return result !== undefined ? result : defaultValue;
}

// --- 组件渲染函数 ---
function renderHomePage() {
    const { title, subtitle } = gameData.config || {};
    document.getElementById('home-title').textContent = title || "伊甸园系统";
    document.getElementById('home-subtitle').textContent = subtitle || "数据加载中...";
    document.getElementById('scene-content').innerHTML = gameData.story?.content || "故事内容加载中...";
    displayChoices(gameData.choices);
}

function renderStatusPage() {
    const tabsContainer = document.getElementById('status-tabs-container');
    const contentContainer = document.getElementById('status-content-container');
    tabsContainer.innerHTML = '';
    contentContainer.innerHTML = '';

    const tabs = gameData.config?.statusTabs || [
        { "id": "overview", "name": "总览" },
        { "id": "user", "name": "{{USER}}详情" },
        { "id": "nanami", "name": "ナナミ详情" },
        { "id": "eden", "name": "伊甸园系统" },
        { "id": "achievements", "name": "成就记录" }
    ];

    tabs.forEach((tab, index) => {
        const isActive = index === 0;
        tabsContainer.innerHTML += `<div class="status-tab ${isActive ? 'active' : ''}" data-tab="${tab.id}">${tab.name}</div>`;
        contentContainer.innerHTML += `<div class="status-content ${isActive ? 'active' : ''}" id="tab-${tab.id}"></div>`;
    });

    document.querySelectorAll('.status-tab').forEach(tab => {
        tab.addEventListener('click', function() {
            document.querySelectorAll('.status-tab').forEach(t => t.classList.remove('active'));
            this.classList.add('active');
            document.querySelectorAll('.status-content').forEach(c => c.classList.remove('active'));
            document.getElementById(`tab-${this.dataset.tab}`).classList.add('active');
        });
    });

    renderStatusOverview();
    renderUserStatus();
    renderNanamiStatus();
    renderEdenStatus();
    renderAchievements();
}

function renderStatusOverview() {
    const container = document.getElementById('tab-overview');
    if (!container) return;

    // 获取所需数据源
    const userPsyState = safeGetValue(gameData, 'characters.user.psychologicalState.content', {});
    const nanamiCoreStatus = safeGetValue(gameData, 'characters.nanami.coreStatus.content', {});
    const shopCurrency = safeGetValue(gameData, 'system.shop.currency', 0);
    const edenHealth = safeGetValue(gameData, 'system.eden.health_monitor.content', {});

    // 构建"关系概览"的进度条
    const relationBars = [];
    if (nanamiCoreStatus.resonanceDepth) {
        relationBars.push(createProgressBar(
            nanamiCoreStatus.resonanceDepth.description || '共鸣深度',
            nanamiCoreStatus.resonanceDepth.current,
            nanamiCoreStatus.resonanceDepth.max,
            nanamiCoreStatus.resonanceDepth.barClass
        ));
    }
    if (userPsyState.dependency) {
        relationBars.push(createProgressBar(
            userPsyState.dependency.description || '对ナナミ的依赖程度',
            userPsyState.dependency.current,
            userPsyState.dependency.max,
            userPsyState.dependency.barClass
        ));
    }
     // 共同资产
    relationBars.push(createProgressBar(
        '共同资产',
        shopCurrency,
        1000000, // 假设最大值为1,000,000
        'assets-bar'
    ));

    // 构建"系统状态"的进度条
    const systemBars = [];
    if (edenHealth.stability) {
        systemBars.push(createProgressBar(
            edenHealth.stability.description || '系统稳定性',
            edenHealth.stability.current,
            edenHealth.stability.max,
            edenHealth.stability.barClass
        ));
    }
     if (edenHealth.efficiency) {
        systemBars.push(createProgressBar(
            edenHealth.efficiency.description || '运行效率',
            edenHealth.efficiency.current,
            edenHealth.efficiency.max,
            edenHealth.efficiency.barClass
        ));
    }
    if (nanamiCoreStatus.protocolLevel) {
        systemBars.push(createProgressBar(
            nanamiCoreStatus.protocolLevel.description || '协议激活度',
            nanamiCoreStatus.protocolLevel.current,
            nanamiCoreStatus.protocolLevel.max,
            nanamiCoreStatus.protocolLevel.barClass
        ));
    }


    container.innerHTML = `
        <div class="status-grid">
            <div class="status-card">
                <h3><i class="fas fa-heart"></i> 关系概览</h3>
                ${relationBars.join('')}
            </div>
            <div class="status-card">
                <h3><i class="fas fa-cog"></i> 系统状态</h3>
                ${systemBars.join('')}
            </div>
        </div>`;
}

function renderDataDrivenContent(container, dataObject) {
    container.innerHTML = '';

    if (!dataObject) {
        container.innerHTML = '<p style="text-align: center; color: #999;">暂无数据</p>';
        return;
    }

    for (const key in dataObject) {
        if (typeof dataObject[key] === 'object' && dataObject[key] !== null) {
            const block = dataObject[key];
            let html = '';

            if (block.type) {
                switch (block.type) {
                    case 'details':
                        html = createDetailsSection(block.title, block.content);
                        break;
                    case 'progress_bars':
                        html = createProgressBarsSection(block.title, block.content);
                        break;
                    case 'status_values':
                        html = createStatusValuesSection(block.title, block.content);
                        break;
                    case 'traits':
                        html = createTraitsSection(block.title, block.content);
                        break;
                }
            } else if (Array.isArray(block)) {
                // 处理简单数组格式（如details）
                html = createDetailsSection(key, block);
            } else if (block.current !== undefined && block.max !== undefined) {
                // 处理进度条格式
                html = createProgressBarsSection(key, { [key]: block });
            }

            container.innerHTML += html;
        }
    }
}

function createDetailsSection(title, details) {
    if (!Array.isArray(details)) return '';

    const detailsHtml = details.map(detail => `
        <div class="detail-label">${detail.label || detail.key}</div>
        <div class="detail-value">${detail.value}</div>
    `).join('');

    const isErotic = title.includes('情色') || title.includes('性器') || title.includes('体液');
    const sectionClass = isErotic ? 'detail-section erotic-status' : 'detail-section';

    return `
        <div class="${sectionClass}">
            <h4>${title}</h4>
            <div class="detail-grid">${detailsHtml}</div>
        </div>`;
}

function createProgressBarsSection(title, progressBars) {
    const barsHtml = Object.entries(progressBars).map(([key, bar]) =>
        createProgressBar(bar.description || key, bar.current, bar.max, bar.barClass || 'protocol-bar')
    ).join('');
    return `
        <div class="detail-section">
            <h4>${title}</h4>
            ${barsHtml}
        </div>`;
}

function createStatusValuesSection(title, statuses) {
    const statusHtml = Object.entries(statuses).map(([key, value]) => `
        <div class="detail-label">${value.description || key}</div>
        <div class="detail-value special-value">${value.current}${key === 'happiness' ? '%' : ''}</div>
    `).join('');
    return `
        <div class="detail-section">
            <h4>${title}</h4>
            <div class="detail-grid">${statusHtml}</div>
        </div>`;
}

function createTraitsSection(title, traits) {
    if (!Array.isArray(traits)) return '';

    const traitsHtml = traits.map(trait => `
        <div class="detail-label">${trait.name}</div>
        <div class="detail-value">${trait.unlocked ? '已解锁' : '未解锁'}</div>
    `).join('');
    return `
        <div class="detail-section">
            <h4>${title}</h4>
            <div class="detail-grid">${traitsHtml}</div>
        </div>`;
}

function renderUserStatus() {
    const container = document.getElementById('tab-user');
    const userData = gameData.characters?.user;
    renderDataDrivenContent(container, userData);
}

function renderNanamiStatus() {
    const container = document.getElementById('tab-nanami');
    const nanamiData = gameData.characters?.nanami;
    renderDataDrivenContent(container, nanamiData);
}

function renderEdenStatus() {
    const container = document.getElementById('tab-eden');
    const edenData = gameData.system?.eden;
    renderDataDrivenContent(container, edenData);
}

function renderAchievements() {
    const grid = document.getElementById('tab-achievements');
    grid.innerHTML = '<h3>成就记录</h3><div class="achievement-grid"></div>';
    const achievementGrid = grid.querySelector('.achievement-grid');

    const achievements = gameData.archives?.achievements || [];
    achievements.forEach(ach => {
        achievementGrid.innerHTML += `
            <div class="achievement-card ${ach.unlocked ? 'unlocked' : 'locked'}">
                <div class="achievement-icon">${ach.icon}</div>
                <div class="achievement-name">${ach.name}</div>
                <div class="achievement-desc">${ach.desc}</div>
                ${ach.unlocked ? `<div class="achievement-date">${formatDate(ach.date)}</div>` : ''}
            </div>
        `;
    });
}

function renderShop() {
    const container = document.getElementById('shop-items');
    container.innerHTML = '';
    const currency = gameData.system?.shop?.currency || 0;
    document.getElementById('shop-currency').textContent = currency.toLocaleString();

    const items = gameData.system?.shop?.items || [];
    items.forEach(item => {
        container.innerHTML += `
            <div class="shop-item">
                <div class="shop-item-icon">${item.icon}</div>
                <div class="shop-item-name">${item.name}</div>
                <div class="shop-item-desc">${item.description}</div>
                <div class="shop-item-price">
                    <span class="price-tag">¥${item.price.toLocaleString()}</span>
                    <button class="buy-button" onclick="buyItem('${item.id}')">购买</button>
                </div>
            </div>
        `;
    });
}

function renderStorage() {
    const grid = document.getElementById('storage-grid');
    grid.innerHTML = '';
    const inventory = gameData.system?.storage?.inventory || [];
    const totalSlots = Math.max(20, inventory.length);

    for (let i = 0; i < totalSlots; i++) {
        const item = inventory[i];
        if (item) {
             grid.innerHTML += `
                <div class="storage-slot filled" onclick="showItemActions('${item.id}', ${i})">
                    <div class="storage-icon">${item.icon}</div>
                    <div class="storage-quantity">${item.quantity || 1}</div>
                </div>`;
        } else {
             grid.innerHTML += `<div class="storage-slot"></div>`;
        }
    }
}

// --- 游戏逻辑和交互 ---
function logUserAction(type, details) {
    userActionLog.push({ type, ...details, timestamp: new Date().toISOString() });
    console.log("Action logged:", { type, ...details });
}

function buyItem(itemId) {
    const item = gameData.system?.shop?.items?.find(i => i.id === itemId);
    if (!item) {
        showModal('错误', '找不到该物品。');
        return;
    }
    const currentCurrency = gameData.system?.shop?.currency || 0;
    if (currentCurrency < item.price) {
        showModal('资金不足', '您的资产不足以购买此物品。');
        return;
    }

    gameData.system.shop.currency -= item.price;
    logUserAction('购买物品', { itemId: item.id, itemName: item.name, price: item.price });

    document.getElementById('shop-currency').textContent = gameData.system.shop.currency.toLocaleString();

    showModal('购买成功', `购买【${item.name}】的指令已记录。您的选择将在下一次与ナナミ交互时一同提交。`);
}

function showItemActions(itemId, itemIndex) {
    const inventory = gameData.system?.storage?.inventory || [];
    const item = inventory.find(i => i.id === itemId);

    if (!item) {
        showModal('错误', '找不到该物品。');
        return;
    }

    showModal(
        item.name,
        item.description,
        [
            {
                text: '使用',
                class: 'primary',
                action: () => {
                    logUserAction('使用物品', { itemId: item.id, itemName: item.name });
                    item.quantity = (item.quantity || 1) - 1;
                    if (item.quantity <= 0) {
                        gameData.system.storage.inventory = inventory.filter(i => i.id !== itemId);
                    }
                    renderStorage();
                    hideModal();
                }
            },
            {
                text: '丢弃',
                class: 'secondary',
                action: () => {
                    logUserAction('丢弃物品', { itemId: item.id, itemName: item.name });
                    item.quantity = (item.quantity || 1) - 1;
                    if (item.quantity <= 0) {
                         gameData.system.storage.inventory = inventory.filter(i => i.id !== itemId);
                    }
                    renderStorage();
                    hideModal();
                }
            },
            {
                text: '取消',
                class: 'secondary',
                action: hideModal
            }
        ]
    );
}

function displayChoices(choices) {
    const list = document.getElementById('choice-list');
    const panel = document.getElementById('choices-panel');
    if (!choices || choices.length === 0) {
        panel.style.display = 'none';
        return;
    }
    panel.style.display = 'block';
    list.innerHTML = choices.map(choice =>
        `<button class="choice-button" onclick="handleChoice(this, \`${choice.text.replace(/'/g, "\\'")}\`)">${choice.text}</button>`
    ).join('');
    document.getElementById('choices-content').classList.remove('collapsed');
    document.getElementById('choices-toggle').classList.remove('collapsed');
}

function exportDataToST() {
    try {
        console.log('🔄 准备导出数据...');

        const exportData = {
            json_data_table: {
                gameData: { ...gameData }
            },
            export_info: {
                type: '伊甸园数据导出',
                timestamp: new Date().toISOString(),
                userActions: userActionLog.length
            }
        };

        delete exportData.json_data_table.gameData.story;
        delete exportData.json_data_table.gameData.choices;

        cachedExportData = exportData;
        console.log('✅ 数据已缓存');
        showModal('数据已准备', '完整的游戏状态数据已缓存，将在您下一次做出选择时一同发送至SillyTavern。');
    } catch (error) {
        console.error('❌ 导出数据失败:', error);
        showModal('导出失败', `无法准备数据: ${error.message}`);
    }
}

function handleChoice(button, text) {
    console.log(`玩家选择: ${text}`);

    let message = text;
    let systemLog = '';

    if (cachedExportData) {
        console.log('📦 发现缓存数据，将与选择一同发送');
        const dataString = JSON.stringify(cachedExportData, null, 2);
        systemLog += `【系统】伊甸园数据更新\n\`\`\`json\n${dataString}\n\`\`\`\n\n`;
        cachedExportData = null;
        console.log('✅ 缓存数据已发送并清除');
    }

    if (userActionLog.length > 0) {
        const actions = userActionLog.map(log => {
            const actionData = { ...log };
            const type = actionData.type;
            delete actionData.type;
            return { [type]: actionData };
        });

        const logString = jsyaml.dump({
            '系统自动记录': actions
        }, { indent: 2, lineWidth: -1 });

        message += `\n\n${logString}`;
        userActionLog = [];
    }

    const finalMessage = systemLog + `{{USER}} [选择] ${message}`;

    if (typeof window.triggerSlash === 'function') {
        window.triggerSlash(`/send ${finalMessage}|/trigger`);
    } else {
        showModal('提示', `已选择: "${message}"<br><small>(SillyTavern接口未找到，无法发送)</small>`);
    }
    document.getElementById('choices-panel').style.display = 'none';
}

// --- 工具函数 ---
function createProgressBar(label, current, max, barClass) {
    const percentage = Math.max(0, Math.min(100, (current / max) * 100));
    return `
        <div class="progress-item">
            <div class="progress-label"><span>${label}</span><span>${current.toLocaleString()} / ${max.toLocaleString()}</span></div>
            <div class="progress-bar"><div class="progress-fill ${barClass}" style="width: ${percentage}%"></div></div>
        </div>`;
}

function toggleChoices() {
    const content = document.getElementById('choices-content');
    const toggle = document.getElementById('choices-toggle');
    content.classList.toggle('collapsed');
    toggle.classList.toggle('collapsed');
}

function showModal(title, content, buttons = null) {
    document.getElementById('modal-title').textContent = title;
    document.getElementById('modal-content').innerHTML = content;
    const buttonsContainer = document.getElementById('modal-buttons');
    buttonsContainer.innerHTML = '';
    if (!buttons) {
        buttons = [{ text: '确定', class: 'primary', action: hideModal }];
    }
    buttons.forEach(btnInfo => {
        const btn = document.createElement('button');
        btn.className = `modal-button ${btnInfo.class}`;
        btn.textContent = btnInfo.text;
        btn.onclick = btnInfo.action;
        buttonsContainer.appendChild(btn);
    });
    document.querySelector('.modal-overlay').style.display = 'flex';
}

function hideModal() {
    document.querySelector('.modal-overlay').style.display = 'none';
}

function formatDate(dateStr) {
    const date = new Date(dateStr);
    return new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(date);
}

</script>
</body>
</html>

