/**
 * AI回复JSON提取器
 * 功能：从最新AI回复中提取JSON/YAML内容，根据声明对聊天变量表进行增删查改操作
 * 支持：JSON优先，YAML备选，混合模式（多个操作顺序执行）
 * 作者：基于变量表.JS优化
 */

// 动态加载js-yaml库
if (typeof window.jsyaml === 'undefined') {
    const script = document.createElement('script');
    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/js-yaml/4.1.0/js-yaml.min.js';
    script.onload = () => {
        console.log('[YAML支持] js-yaml库加载成功');
        window.jsyaml = jsyaml;
    };
    script.onerror = () => {
        console.warn('[YAML支持] js-yaml库加载失败，YAML功能将不可用');
    };
    document.head.appendChild(script);
}

class AIReplyJSONExtractor {
    constructor() {
        this.variableTableKey = 'json_data_table'; // JSON数据表键名
        this.operationLogKey = 'json_operations_log'; // 操作日志键名
        this.enableLogging = false; // 是否启用日志记录
    }

    /**
     * 根据消息ID获取AI的回复内容，并验证是否为AI回复
     * @param {number} messageId - 消息ID
     * @returns {Promise<string|null>} AI回复内容，如果不是AI回复则返回null
     */
    async getVerifiedAIReplyById(messageId) {
        try {
            const messages = await getChatMessages(`${messageId}-${messageId}`);
            if (!messages || messages.length === 0) {
                console.log(`[AI回复提取] 未找到ID为 ${messageId} 的消息`);
                return null;
            }

            const message = messages[0];

            // 主要判断依据：role属性
            const isAIReply = message.role === 'assistant';
            // 兼容性判断：检查is_user属性
            const isNotUser = message.is_user === false;

            if (isAIReply || isNotUser) {
                console.log(`[AI回复提取] 确认ID ${messageId} 为AI回复 (role: ${message.role}, is_user: ${message.is_user})。`);
                const reply = message.message;
                console.log(`[AI回复提取] 获取到AI回复，长度: ${reply.length} 字符`);
                return reply;
            } else {
                console.log(`[AI回复提取] ID ${messageId} 不是AI回复 (role: ${message.role}, is_user: ${message.is_user})，跳过处理。`);
                return null;
            }
        } catch (error) {
            console.error(`[AI回复提取] 获取或验证ID为 ${messageId} 的AI回复失败:`, error);
            return null;
        }
    }

    /**
     * 从文本中提取YAML内容
     * @param {string} text - 要提取的文本
     * @returns {Object|null} 提取到的YAML对象
     */
    extractYAMLFromText(text) {
        if (!text || typeof window.jsyaml === 'undefined') {
            if (typeof window.jsyaml === 'undefined') {
                console.log('[YAML提取] js-yaml库未加载，跳过YAML提取');
            }
            return null;
        }

        try {
            console.log('[YAML提取] 开始提取YAML内容...');

            // YAML提取模式
            const yamlPatterns = [
                // 匹配```yaml...```格式
                /```yaml\s*([\s\S]*?)\s*```/gi,
                // 匹配```yml...```格式
                /```yml\s*([\s\S]*?)\s*```/gi,
                // 匹配以---开头的YAML格式
                /^---\s*\n([\s\S]*?)(?:\n---|\n\.\.\.|$)/gm
            ];

            for (let i = 0; i < yamlPatterns.length; i++) {
                const pattern = yamlPatterns[i];
                const matches = text.match(pattern);

                if (matches) {
                    console.log(`[YAML提取] 使用模式${i+1}找到${matches.length}个匹配项`);

                    for (const match of matches) {
                        try {
                            // 清理代码块标记
                            let cleanYaml = match
                                .replace(/```yaml\s*/g, '')
                                .replace(/```yml\s*/g, '')
                                .replace(/```\s*/g, '')
                                .replace(/^---\s*\n/g, '')
                                .replace(/\n---$/g, '')
                                .replace(/\n\.\.\.$/g, '')
                                .trim();

                            const parsed = window.jsyaml.load(cleanYaml);

                            if (parsed && typeof parsed === 'object') {
                                console.log('[YAML提取] 成功提取YAML对象:', Object.keys(parsed));
                                return parsed;
                            }
                        } catch (e) {
                            console.log('[YAML提取] 解析YAML失败:', e.message);
                            continue; // 尝试下一个匹配项
                        }
                    }
                }
            }

            // 尝试直接解析整个文本为YAML
            console.log('[YAML提取] 尝试直接解析整个文本为YAML...');
            const parsed = window.jsyaml.load(text);
            if (parsed && typeof parsed === 'object') {
                console.log('[YAML提取] 成功解析整个文本为YAML');
                return parsed;
            }

        } catch (error) {
            console.log('[YAML提取] 未能提取到有效YAML:', error.message);
        }

        return null;
    }

    /**
     * 从文本中提取多个JSON/YAML块（混合模式）
     * @param {string} text - 要提取的文本
     * @returns {Array} 提取到的数据块数组
     */
    extractMultipleDataBlocks(text) {
        if (!text) return [];

        console.log('[混合模式] 开始提取多个数据块...');
        const dataBlocks = [];

        // 定义所有可能的数据块模式（优先级从高到低）
        const patterns = [
            // YAML相关模式（优先级更高，避免被通用模式覆盖）
            { type: 'yaml', pattern: /```yaml\s*([\s\S]*?)\s*```/gi, priority: 1 },
            { type: 'yaml', pattern: /```yml\s*([\s\S]*?)\s*```/gi, priority: 1 },
            { type: 'yaml', pattern: /^---\s*\n([\s\S]*?)(?:\n---|\n\.\.\.|$)/gm, priority: 1 },
            // JSON相关模式
            { type: 'json', pattern: /```json\s*([\s\S]*?)\s*```/gi, priority: 2 },
            { type: 'json', pattern: /\{[\s\S]*?\}/g, priority: 3 },
            // 通用代码块模式（最低优先级，只匹配不被其他模式覆盖的）
            { type: 'json', pattern: /```\s*([\s\S]*?)\s*```/gi, priority: 4 }
        ];

        // 收集所有匹配项及其位置
        const allMatches = [];

        for (const patternInfo of patterns) {
            let match;
            const regex = new RegExp(patternInfo.pattern.source, patternInfo.pattern.flags);

            while ((match = regex.exec(text)) !== null) {
                allMatches.push({
                    type: patternInfo.type,
                    content: match[1] || match[0],
                    start: match.index,
                    end: match.index + match[0].length,
                    raw: match[0],
                    priority: patternInfo.priority
                });
            }
        }

        // 按位置排序
        allMatches.sort((a, b) => a.start - b.start);

        // 智能去重：保留优先级更高的匹配项
        const uniqueMatches = [];
        for (const match of allMatches) {
            const overlapping = uniqueMatches.filter(existing => 
                (match.start >= existing.start && match.start < existing.end) ||
                (match.end > existing.start && match.end <= existing.end) ||
                (existing.start >= match.start && existing.start < match.end) ||
                (existing.end > match.start && existing.end <= match.end)
            );

            if (overlapping.length === 0) {
                // 没有重叠，直接添加
                uniqueMatches.push(match);
            } else {
                // 有重叠，检查优先级
                const lowestPriority = Math.min(...overlapping.map(m => m.priority));
                if (match.priority <= lowestPriority) {
                    // 当前匹配项优先级更高或相等，移除重叠的低优先级项
                    for (let i = uniqueMatches.length - 1; i >= 0; i--) {
                        const existing = uniqueMatches[i];
                        const isOverlapping = 
                            (match.start >= existing.start && match.start < existing.end) ||
                            (match.end > existing.start && match.end <= existing.end) ||
                            (existing.start >= match.start && existing.start < match.end) ||
                            (existing.end > match.start && existing.end <= match.end);

                        if (isOverlapping && existing.priority >= match.priority) {
                            uniqueMatches.splice(i, 1);
                        }
                    }
                    uniqueMatches.push(match);
                }
            }
        }

        // 重新按位置排序
        uniqueMatches.sort((a, b) => a.start - b.start);

        console.log(`[混合模式] 找到${uniqueMatches.length}个候选数据块`);

        // 解析每个数据块
        for (let i = 0; i < uniqueMatches.length; i++) {
            const match = uniqueMatches[i];
            try {
                let parsed = null;
                let cleanContent = match.content;

                if (match.type === 'json') {
                    // 清理JSON内容
                    cleanContent = cleanContent
                        .replace(/```json\s*/g, '')
                        .replace(/```\s*/g, '')
                        .trim();

                    parsed = JSON.parse(cleanContent);
                } else if (match.type === 'yaml' && typeof window.jsyaml !== 'undefined') {
                    // 清理YAML内容
                    cleanContent = cleanContent
                        .replace(/```yaml\s*/g, '')
                        .replace(/```yml\s*/g, '')
                        .replace(/```\s*/g, '')
                        .replace(/^---\s*\n/g, '')
                        .replace(/\n---$/g, '')
                        .replace(/\n\.\.\.$/g, '')
                        .trim();

                    parsed = window.jsyaml.load(cleanContent);
                }

                if (parsed && typeof parsed === 'object') {
                    dataBlocks.push({
                        index: i,
                        type: match.type,
                        data: parsed,
                        position: match.start
                    });
                    console.log(`[混合模式] 成功解析第${i+1}个${match.type.toUpperCase()}块:`, Object.keys(parsed));
                }
            } catch (error) {
                console.log(`[混合模式] 解析第${i+1}个${match.type.toUpperCase()}块失败:`, error.message);
            }
        }

        console.log(`[混合模式] 总共提取到${dataBlocks.length}个有效数据块`);
        return dataBlocks;
    }

    /**
     * 从文本中提取JSON/YAML内容（优先JSON，支持混合模式）
     * @param {string} text - 要提取的文本
     * @returns {Object|Array|null} 提取到的数据对象或数据块数组
     */
    extractDataFromText(text) {
        if (!text) return null;

        try {
            console.log('[数据提取] 开始提取JSON/YAML内容...');

            // 首先尝试提取多个数据块（混合模式）
            const multipleBlocks = this.extractMultipleDataBlocks(text);
            if (multipleBlocks.length > 1) {
                console.log(`[数据提取] 检测到混合模式，包含${multipleBlocks.length}个数据块`);
                return multipleBlocks;
            } else if (multipleBlocks.length === 1) {
                console.log('[数据提取] 单个数据块模式');
                return multipleBlocks[0].data;
            }

            // 如果没有找到多个块，尝试单个JSON提取
            console.log('[数据提取] 尝试单个JSON提取...');
            const jsonResult = this.extractJSONFromText(text);
            if (jsonResult) {
                console.log('[数据提取] JSON提取成功');
                return jsonResult;
            }

            // 如果JSON失败，尝试YAML提取
            console.log('[数据提取] JSON提取失败，尝试YAML提取...');
            const yamlResult = this.extractYAMLFromText(text);
            if (yamlResult) {
                console.log('[数据提取] YAML提取成功');
                return yamlResult;
            }

            console.log('[数据提取] 未能提取到任何有效数据');
            return null;

        } catch (error) {
            console.error('[数据提取] 提取过程中发生错误:', error);
            return null;
        }
    }

    /**
     * 从文本中提取JSON内容（保持向后兼容）
     * @param {string} text - 要提取的文本
     * @returns {Object|null} 提取到的JSON对象
     */
    extractJSONFromText(text) {
        if (!text) return null;

        try {
            console.log('[JSON提取] 开始提取JSON内容...');

            // 尝试多种JSON提取方法
            const jsonPatterns = [
                // 匹配```json...```格式
                /```json\s*([\s\S]*?)\s*```/gi,
                // 匹配```...```格式（可能是JSON）
                /```\s*([\s\S]*?)\s*```/gi,
                // 匹配{...}格式（完整JSON对象）
                /\{[\s\S]*?\}/g
            ];

            for (let i = 0; i < jsonPatterns.length; i++) {
                const pattern = jsonPatterns[i];
                const matches = text.match(pattern);

                if (matches) {
                    console.log(`[JSON提取] 使用模式${i+1}找到${matches.length}个匹配项`);

                    for (const match of matches) {
                        try {
                            // 清理代码块标记
                            let cleanJson = match
                                .replace(/```json\s*/g, '')
                                .replace(/```\s*/g, '')
                                .trim();

                            const parsed = JSON.parse(cleanJson);

                            if (parsed && typeof parsed === 'object') {
                                console.log('[JSON提取] 成功提取JSON对象:', Object.keys(parsed));
                                return parsed;
                            }
                        } catch (e) {
                            continue; // 尝试下一个匹配项
                        }
                    }
                }
            }

            // 如果以上方法都失败，尝试直接解析整个文本
            console.log('[JSON提取] 尝试直接解析整个文本...');
            return JSON.parse(text);

        } catch (error) {
            console.log('[JSON提取] 未能提取到有效JSON:', error.message);
            return null;
        }
    }

    /**
     * 获取当前的JSON变量表
     * @returns {Object} JSON变量表
     */
    getJSONTable() {
        try {
            const variables = getVariables({ type: 'chat' });
            return variables[this.variableTableKey] || {};
        } catch (error) {
            console.error('[变量表] 获取JSON变量表失败:', error);
            return {};
        }
    }

    /**
     * 记录操作日志
     * @param {string} operation - 操作类型
     * @param {Object} data - 操作数据
     */
    async logOperation(operation, data) {
        if (!this.enableLogging) return;

        try {
            const variables = getVariables({ type: 'chat' });
            const logs = variables[this.operationLogKey] || [];

            logs.push({
                timestamp: new Date().toISOString(),
                operation: operation,
                data: JSON.stringify(data, null, 2)
            });

            // 只保留最近30条日志（避免占用过多空间）
            if (logs.length > 30) {
                logs.splice(0, logs.length - 30);
            }

            await insertOrAssignVariables({
                [this.operationLogKey]: logs
            }, { type: 'chat' });
        } catch (error) {
            console.error('[日志记录] 记录操作日志失败:', error);
        }
    }

    /**
     * 检测JSON中的操作类型和数据结构
     * @param {Object} jsonData - JSON数据
     * @returns {Object} 操作分析结果
     */
    analyzeJSONOperations(jsonData) {
        const analysis = {
            operationType: 'replace', // 默认为替换操作
            hasOperationFlags: false,
            data: jsonData
        };

        // 检查是否有操作标识
        if (jsonData.hasOwnProperty('$operation')) {
            analysis.hasOperationFlags = true;
            analysis.operationType = jsonData.$operation;
            analysis.data = { ...jsonData };
            delete analysis.data.$operation;
        } else if (jsonData.hasOwnProperty('$update')) {
            analysis.hasOperationFlags = true;
            analysis.operationType = 'update';
            analysis.data = jsonData.$update;
        } else if (jsonData.hasOwnProperty('$delete')) {
            analysis.hasOperationFlags = true;
            analysis.operationType = 'delete';
            analysis.deletePaths = Array.isArray(jsonData.$delete) ? jsonData.$delete : [jsonData.$delete];
        } else if (jsonData.hasOwnProperty('$clear')) {
            analysis.hasOperationFlags = true;
            analysis.operationType = 'clear';
        }

        console.log(`[操作分析] 检测到操作类型: ${analysis.operationType}`);
        return analysis;
    }

    /**
     * 深度拷贝对象
     * @param {Object} obj - 要拷贝的对象
     * @returns {Object} 拷贝后的对象
     */
    deepCopy(obj) {
        if (obj === null || typeof obj !== 'object') {
            return obj;
        }

        if (Array.isArray(obj)) {
            return obj.map(item => this.deepCopy(item));
        }

        const copy = {};
        for (const key in obj) {
            if (obj.hasOwnProperty(key)) {
                copy[key] = this.deepCopy(obj[key]);
            }
        }

        return copy;
    }

    /**
     * 根据路径设置对象的属性值，如果路径不存在则会创建
     * @param {Object} obj - 目标对象
     * @param {string} path - 属性路径，如 "用户信息.姓名"
     * @param {any} value - 要设置的值
     */
    setByPath(obj, path, value) {
        const keys = path.split('.');
        let current = obj;

        for (let i = 0; i < keys.length - 1; i++) {
            const key = keys[i];
            // 如果路径中的节点不是对象或不存在，则创建它
            if (typeof current[key] !== 'object' || current[key] === null) {
                current[key] = {};
            }
            current = current[key];
        }

        const lastKey = keys[keys.length - 1];
        current[lastKey] = value;
        console.log(`[路径更新] 成功设置路径 "${path}"`);
    }

    /**
     * 深度合并对象
     * @param {Object} target - 目标对象
     * @param {Object} source - 源对象
     * @returns {Object} 合并后的对象
     */
    deepMerge(target, source) {
        const result = { ...target };

        for (const key in source) {
            if (source.hasOwnProperty(key)) {
                if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
                    result[key] = this.deepMerge(result[key] || {}, source[key]);
                } else {
                    result[key] = source[key];
                }
            }
        }

        return result;
    }

    /**
     * 根据路径删除对象属性
     * @param {Object} obj - 目标对象
     * @param {string} path - 属性路径，如 "用户信息.姓名"
     */
    deleteByPath(obj, path) {
        const keys = path.split('.');
        let current = obj;

        // 遍历到倒数第二级对象
        for (let i = 0; i < keys.length - 1; i++) {
            if (current[keys[i]] && typeof current[keys[i]] === 'object') {
                current = current[keys[i]];
            } else {
                console.log(`[删除] 路径 "${path}" 中的 "${keys[i]}" 不存在或不是对象`);
                return false;
            }
        }

        const lastKey = keys[keys.length - 1];
        if (current.hasOwnProperty(lastKey)) {
            delete current[lastKey];
            console.log(`[删除] 成功删除路径 "${path}"`);
            return true;
        } else {
            console.log(`[删除] 路径 "${path}" 的最终键 "${lastKey}" 不存在`);
            return false;
        }
    }

    /**
     * 执行JSON操作并更新变量表
     * @param {Object} analysis - 操作分析结果
     * @returns {boolean} 操作是否成功
     */
    async executeJSONOperations(analysis) {
        try {
            const currentTable = this.getJSONTable();
            let newTable;
            let operationDesc = '';

            switch (analysis.operationType) {
                case 'replace':
                    // 无声明标识 = 清空旧数据然后写入新数据（完整替换）
                    newTable = analysis.data;
                    operationDesc = '完整替换';
                    console.log(`[变量更新] 执行完整替换操作，新数据键: ${Object.keys(newTable)}`);
                    break;

                case 'update':
                    // 增量更新，支持路径更新
                    newTable = this.deepCopy(currentTable); // 使用深拷贝以避免修改原始对象
                    operationDesc = '增量更新';
                    console.log(`[变量更新] 执行增量更新操作，更新内容:`, analysis.data);

                    for (const key in analysis.data) {
                        if (analysis.data.hasOwnProperty(key)) {
                            const value = analysis.data[key];
                            if (key.includes('.')) {
                                // 识别为路径更新
                                this.setByPath(newTable, key, value);
                            } else {
                                // 识别为顶层或嵌套对象合并
                                if (typeof newTable[key] === 'object' && newTable[key] !== null && typeof value === 'object' && value !== null && !Array.isArray(value)) {
                                    newTable[key] = this.deepMerge(newTable[key], value);
                                } else {
                                    newTable[key] = value;
                                }
                            }
                        }
                    }
                    break;

                case 'delete':
                    // 使用专门的删除变量函数
                    let deletedCount = 0;
                    for (const path of analysis.deletePaths || []) {
                        try {
                            // 构建完整的变量路径：json_data_table.用户信息.年龄
                            const fullPath = `${this.variableTableKey}.${path}`;
                            const success = await deleteVariable(fullPath, { type: 'chat' });
                            if (success) {
                                deletedCount++;
                                console.log(`[变量更新] 删除路径: ${path} - 成功`);
                            } else {
                                console.log(`[变量更新] 删除路径: ${path} - 失败（路径不存在）`);
                            }
                        } catch (error) {
                            console.error(`[变量更新] 删除路径 ${path} 失败:`, error);
                        }
                    }
                    operationDesc = `删除 ${deletedCount}/${analysis.deletePaths?.length || 0} 项`;

                    // 删除操作不需要再次更新变量表，因为deleteVariable已经直接操作了
                    await this.logOperation(`AI回复-${operationDesc}`, {
                        operationType: analysis.operationType,
                        dataKeys: [],
                        deletePaths: analysis.deletePaths || null
                    });

                    console.log(`[变量更新] ${operationDesc}操作成功完成`);
                    return true;

                case 'clear':
                    // 清空所有数据
                    newTable = {};
                    operationDesc = '清空所有数据';
                    console.log('[变量更新] 执行清空操作');
                    break;

                default:
                    console.warn(`[变量更新] 未知操作类型: ${analysis.operationType}`);
                    return false;
            }

            // 更新变量表
            await insertOrAssignVariables({
                [this.variableTableKey]: newTable
            }, { type: 'chat' });

            // 记录操作日志
            await this.logOperation(`AI回复-${operationDesc}`, {
                operationType: analysis.operationType,
                dataKeys: analysis.data ? Object.keys(analysis.data) : [],
                deletePaths: analysis.deletePaths || null
            });

            console.log(`[变量更新] ${operationDesc}操作成功完成`);
            return true;

        } catch (error) {
            console.error('[变量更新] 执行操作失败:', error);
            return false;
        }
    }

    /**
     * 处理混合模式数据（多个操作顺序执行）
     * @param {Array} dataBlocks - 数据块数组
     * @returns {boolean} 处理是否成功
     */
    async processMixedModeData(dataBlocks) {
        console.log(`\n=== 开始处理混合模式数据（${dataBlocks.length}个操作）===`);

        let successCount = 0;
        let totalOperations = dataBlocks.length;

        for (let i = 0; i < dataBlocks.length; i++) {
            const block = dataBlocks[i];

            try {
                console.log(`\n--- 处理第${i+1}/${totalOperations}个操作 (${block.type.toUpperCase()}) ---`);

                // 分析操作类型
                const analysis = this.analyzeJSONOperations(block.data);

                // 执行操作
                const success = await this.executeJSONOperations(analysis);

                if (success) {
                    successCount++;
                    console.log(`[混合模式] 第${i+1}个操作执行成功`);
                } else {
                    console.log(`[混合模式] 第${i+1}个操作执行失败`);
                }

                // 添加短暂延迟以确保操作之间的顺序性
                await new Promise(resolve => setTimeout(resolve, 100));

            } catch (error) {
                console.error(`[混合模式] 第${i+1}个操作处理异常:`, error);
            }
        }

        console.log(`\n[混合模式] 处理完成：${successCount}/${totalOperations} 个操作成功`);

        // 记录混合模式操作日志
        await this.logOperation(`AI回复-混合模式(${successCount}/${totalOperations})`, {
            operationType: 'mixed',
            totalOperations: totalOperations,
            successCount: successCount,
            operations: dataBlocks.map((block, index) => ({
                index: index + 1,
                type: block.type,
                operationType: this.analyzeJSONOperations(block.data).operationType
            }))
        });

        return successCount > 0;
    }

    /**
     * 主要处理函数：从AI回复中提取JSON/YAML并更新变量表（支持混合模式）
     * @param {number} messageId - 触发事件的消息ID
     * @returns {boolean} 处理是否成功
     */
    async processAIReplyToJSON(messageId) {
        try {
            console.log(`\n=== 开始处理ID为 ${messageId} 的AI回复数据 ===`);

            // 1. 根据消息ID获取并验证AI回复
            const aiReply = await this.getVerifiedAIReplyById(messageId);
            if (!aiReply) {
                // getVerifiedAIReplyById 内部已打印日志，此处无需重复
                return false;
            }

            // 2. 提取数据内容（JSON优先，YAML备选，支持混合模式）
            const extractedData = this.extractDataFromText(aiReply);
            if (!extractedData) {
                console.log('[处理失败] 未从AI回复中提取到有效数据');
                return false;
            }

            // 3. 判断是否为混合模式
            if (Array.isArray(extractedData)) {
                // 混合模式：多个操作顺序执行
                const success = await this.processMixedModeData(extractedData);

                if (success) {
                    console.log('[处理成功] 混合模式数据已处理完成');
                    this.showCurrentStatus();
                    return true;
                } else {
                    console.log('[处理失败] 混合模式处理时发生错误');
                    return false;
                }
            } else {
                // 单一模式：单个操作
                console.log('[数据处理] 单一模式处理');

                // 分析操作类型
                const analysis = this.analyzeJSONOperations(extractedData);

                // 执行操作并更新变量表
                const success = await this.executeJSONOperations(analysis);

                if (success) {
                    console.log('[处理成功] 数据已更新到聊天变量表');
                    this.showCurrentStatus();
                    return true;
                } else {
                    console.log('[处理失败] 更新变量表时发生错误');
                    return false;
                }
            }

        } catch (error) {
            console.error('[处理异常] 处理AI回复失败:', error);
            return false;
        }
    }

    /**
     * 显示当前变量表状态
     */
    showCurrentStatus() {
        console.log('\n=== 当前JSON变量表状态 ===');
        const table = this.getJSONTable();
        const dataSize = JSON.stringify(table).length;
        const keyCount = Object.keys(table).length;

        console.log(`数据大小: ${dataSize} 字符`);
        console.log(`顶级键数量: ${keyCount}`);
        console.log('顶级键名:', Object.keys(table));

        if (keyCount > 0) {
            console.log('完整数据:');
            console.log(JSON.stringify(table, null, 2));
        }
    }

    /**
     * 查询变量表中的特定数据
     * @param {string} path - 查询路径，如 "用户信息.姓名"
     * @returns {any} 查询结果
     */
    queryData(path = null) {
        try {
            const table = this.getJSONTable();

            if (!path) {
                return table;
            }

            const keys = path.split('.');
            let current = table;

            for (const key of keys) {
                if (current && typeof current === 'object' && current.hasOwnProperty(key)) {
                    current = current[key];
                } else {
                    console.log(`[查询] 路径 "${path}" 不存在`);
                    return undefined;
                }
            }

            console.log(`[查询] 路径 "${path}" 的值:`, current);
            return current;
        } catch (error) {
            console.error('[查询] 查询失败:', error);
            return null;
        }
    }

    /**
     * 获取最近的操作日志
     * @param {number} limit - 限制返回的日志条数
     * @returns {Array} 操作日志数组
     */
    getRecentLogs(limit = 5) {
        try {
            const variables = getVariables({ type: 'chat' });
            const logs = variables[this.operationLogKey] || [];
            const recentLogs = logs.slice(-limit);

            console.log(`\n=== 最近${recentLogs.length}条操作日志 ===`);
            recentLogs.forEach((log, index) => {
                console.log(`${index + 1}. ${log.timestamp} - ${log.operation}`);
            });

            return recentLogs;
        } catch (error) {
            console.error('[日志] 获取操作日志失败:', error);
            return [];
        }
    }
}

// 创建全局实例
const aiJSONExtractor = new AIReplyJSONExtractor();

// 导出主要函数供外部调用
window.processAIReplyJSON = (messageId) => aiJSONExtractor.processAIReplyToJSON(messageId);
window.showJSONStatus = () => aiJSONExtractor.showCurrentStatus();
window.queryJSONData = (path) => aiJSONExtractor.queryData(path);
window.getJSONLogs = (limit) => aiJSONExtractor.getRecentLogs(limit);
window.aiJSONExtractor = aiJSONExtractor;



// 使用事件监听器来持续处理新的AI回复
if (typeof tavern_events !== 'undefined' && typeof eventOn === 'function') {
    console.log('[AI回复JSON提取器] 正在监听AI消息渲染完成事件...');

    const handleAiReply = (messageId) => {
        if (messageId === undefined || messageId === null) {
            console.log('[AI回复JSON提取器] 接收到无效的消息ID，跳过处理。');
            return;
        }
        // 添加一个小的延迟以确保消息内容完全可用
        setTimeout(() => {
            // processAIReplyToJSON 内部会进行AI回复的判断
            aiJSONExtractor.processAIReplyToJSON(messageId);
        }, 250); // 稍微增加延迟以确保DOM更新
    };

    // 监听新消息渲染事件，这是最可靠的触发方式
    eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, handleAiReply);

    // 同时监听消息编辑事件，以处理AI回复被编辑后可能需要重新提取数据的情况
    eventOn(tavern_events.MESSAGE_EDITED, (messageId) => {
        console.log(`[AI回复JSON提取器] 检测到消息 ${messageId} 被编辑，将重新处理。`);
        handleAiReply(messageId);
    });

} else {
    console.warn('[AI回复JSON提取器] SillyTavern事件系统 (tavern_events) 未找到，脚本将无法自动运行。');
}
